function showSelection(){document.body.classList.remove('playing','hero-expanded','more-expanded');save();game.mode='select';$('#selection').hidden=false;$('#game').hidden=true;const desc=['공격을 받아치며 보스를 압박하는 검사','분노와 흡혈로 버티는 돌격형 전사','속성과 저주를 다루는 마법사','방패와 용창으로 진격하는 기사','기습과 미끼를 쓰는 날렵한 도적','강화와 재료 회수에 능한 상인','음파와 춤으로 싸우는 음유시인','기공과 자연의 힘을 고르는 격투가','거리를 유지하며 조준하는 궁수','속사와 포격을 선택하는 총잡이','주먹과 신성 마법으로 갈라지는 사제','정령과 영혼을 부르는 소환사'];$('#character-grid').innerHTML=D.characters.map(p=>{const h=game.s.heroes[p.id],job=p.classes[h.cell];return `<button class="character-card" data-select="${p.id}" aria-label="${p.name} ${job.name} 레벨 ${h.level} 선택"><span class="saved">Lv.${h.level}</span><span class="thumb"><canvas width="110" height="110" data-sheet="${p.sheet}" data-cell="${h.cell}" data-height="88" aria-hidden="true"></canvas></span><strong>${p.name}</strong><span class="job">${job.name}</span><small>${desc[p.id]}</small></button>`;}).join('');allThumbs($('#character-grid'));}
async function prepareZone(zone){const r=D.regions[zone];loading=true;const sheets=['characters/'+game.p.slug+'.png','monsters/'+r.id+'.png','monsters/'+r.id+'-bosses.png',r.map];await Promise.allSettled(sheets.map(s=>loadImage(s)));await Promise.allSettled(r.monsters.map(m=>sprite(m.sheet,m.cell)).concat(r.bosses.map(m=>sprite(m.sheet,m.cell))).concat([sprite(game.p.sheet,game.h.cell)]));loading=false;}
async function choose(id){if(loading)return;document.body.classList.add('playing');game.s.active=id;game.mode='loading';document.body.classList.add('playing');$('#selection').hidden=true;$('#game').hidden=false;await prepareZone(Math.floor((game.h.stage-1)/10));game.select(id);headerKey='';portraitKey='';logKey='';paused=false;syncHUD();save();}
async function travel(stage){if(stage>game.h.best)return;closeModal();game.mode='loading';await prepareZone(Math.floor((stage-1)/10));game.start(stage);paused=false;headerKey='';syncHUD();save();}
